def parse_trajectory_id(trajectory_id: str) -> tuple[str, str, int]:
    """Parse 'instance_id__model_name__r{row_index}' into components."""
    parts = trajectory_id.rsplit("__r", 1)
    row_index = int(parts[1])
    prefix = parts[0]
    split = prefix.split("__", 1)
    instance_id = split[0]
    model_name = split[1] if len(split) > 1 else ""
    return instance_id, model_name, row_index


def build_trajectory_index(traj_path: str) -> dict:
    """Map row_index -> list of step dicts with role and text."""
    index = {}
    with open(traj_path) as f:
        for row_idx, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            raw = json.loads(line)
            steps = []
            for s in raw.get("trajectory") or []:
                steps.append({
                    "role": s.get("role", "unknown"),
                    "text": s.get("text") or s.get("system_prompt") or "",
                })
            index[row_idx] = steps
    return index

